<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Elegant Affairs - Catering</title>
    <style>
        :root {
            --primary-red: #E63946;
            --text-dark: #1a1a1a;
            --text-gray: #666666;
            --bg-light: #F9F7F5;
            --font-serif: "Playfair Display", "Didot", "Georgia", serif;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-sans);
            color: var(--text-dark);
            line-height: 1.6;
            background-color: #fff;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        ul {
            list-style: none;
        }

        /* --- Header / Hero Section --- */
        .hero-section {
            position: relative;
            height: 85vh; /* Large hero image */
            width: 100%;
            background-image: url('https://images.unsplash.com/photo-1559339352-11d035aa65de?q=80&w=2074&auto=format&fit=crop'); /* Gourmet food placeholder */
            background-size: cover;
            background-position: center top;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        /* Navigation */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 30px 60px;
            z-index: 10;
        }

        .logo {
            font-family: var(--font-serif);
            font-size: 24px;
            letter-spacing: 1px;
            text-transform: uppercase;
            font-weight: 400;
            color: #333;
            display: flex;
            flex-direction: column;
            line-height: 0.8;
        }

        .logo span {
            /* Simulating the script part of the logo if needed, or just styling the main text */
            font-family: cursive; 
            font-size: 32px;
            color: var(--primary-red);
            margin-bottom: 5px;
        }

        .logo-sub {
            font-family: var(--font-sans);
            font-size: 9px;
            letter-spacing: 3px;
            opacity: 0.7;
            margin-top: 5px;
        }

        nav ul {
            display: flex;
            gap: 25px;
            font-size: 11px;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            font-weight: 500;
        }

        nav ul li a:hover {
            color: var(--primary-red);
        }

        .btn-contact-nav {
            background-color: var(--primary-red);
            color: white !important;
            padding: 12px 24px;
            transition: background 0.3s ease;
        }

        .btn-contact-nav:hover {
            background-color: #c1121f;
        }

        /* Hero Text */
        .hero-text {
            text-align: center;
            padding-bottom: 80px;
            color: white;
            text-shadow: 0 2px 10px rgba(0,0,0,0.3);
        }

        .hero-text h1 {
            font-family: var(--font-serif);
            font-weight: 300;
            font-size: 56px;
            letter-spacing: 1px;
            line-height: 1.2;
        }

        /* --- Location Strip --- */
        .location-strip {
            padding: 40px 20px;
            background-color: white;
            display: flex;
            justify-content: center;
            gap: 80px;
            border-bottom: 1px solid #eee;
        }

        .location-item {
            text-align: center;
            position: relative;
            cursor: pointer;
        }

        .location-item h3 {
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            font-weight: 600;
            margin-bottom: 15px;
        }

        .location-line {
            width: 100px;
            height: 1px;
            background-color: #ccc;
            margin: 0 auto;
            transition: all 0.3s ease;
        }

        .location-item:hover .location-line {
            width: 140px;
            background-color: var(--text-dark);
        }

        /* --- Illustration Section (The Map) --- */
        .illustration-section {
            padding: 60px 20px 120px 20px;
            background-color: white;
            overflow: hidden;
            display: flex;
            justify-content: center;
        }

        .illustration-container {
            max-width: 1200px;
            width: 100%;
            height: auto;
            min-height: 350px;
            /* Using a placeholder that looks like a drawing/map */
            background-image: url('https://images.unsplash.com/photo/1587560699334-cc4ff634909a?q=80&w=2070&auto=format&fit=crop'); 
            background-repeat: no-repeat;
            background-position: center bottom;
            background-size: contain;
            filter: grayscale(20%) contrast(90%);
            opacity: 0.9;
        }

        /* Since I can't generate the exact vector art, I will use a styled container to represent it */
        .map-placeholder-svg {
            width: 100%;
            height: 100%;
            display: block;
        }


        /* --- Spacer Sections (Beige Blocks) --- */
        .spacer-block {
            background-color: var(--bg-light);
            height: 600px; /* Tall blocks as seen in screenshot */
            width: 100%;
        }

        /* --- Footer --- */
        footer {
            background-color: white;
            padding: 80px 60px;
            border-top: 1px solid #eee;
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 40px;
        }

        /* Footer Left */
        .footer-left h2 {
            font-family: var(--font-serif);
            font-size: 28px;
            font-weight: 400;
            margin-bottom: 15px;
        }

        .footer-link {
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            text-decoration: underline;
            color: var(--text-dark);
            display: inline-block;
            margin-bottom: 25px;
        }

        .social-icons {
            display: flex;
            gap: 15px;
        }

        .social-icon {
            width: 32px;
            height: 32px;
            background-color: var(--primary-red);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 14px;
            transition: transform 0.2s;
        }

        .social-icon:hover {
            transform: scale(1.1);
        }

        /* Footer Center (Addresses) */
        .footer-center {
            display: flex;
            justify-content: center;
            gap: 30px;
            font-size: 9px;
            line-height: 1.6;
            color: #444;
            text-align: left;
        }

        .address-col strong {
            display: block;
            margin-bottom: 4px;
            color: #000;
        }

        /* Footer Right (Newsletter) */
        .footer-right {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            text-align: right;
        }

        .newsletter-label {
            font-size: 11px;
            letter-spacing: 2px;
            text-transform: uppercase;
            margin-bottom: 15px;
            font-weight: 500;
        }

        .newsletter-form {
            display: flex;
            gap: 10px;
            width: 100%;
            justify-content: flex-end;
        }

        .form-input {
            border: 1px solid #ddd;
            padding: 10px;
            font-size: 11px;
            width: 120px;
            outline: none;
            font-family: inherit;
        }

        .form-input:focus {
            border-color: var(--primary-red);
        }

        .btn-submit {
            background-color: var(--primary-red);
            color: white;
            border: none;
            padding: 10px 25px;
            font-size: 11px;
            cursor: pointer;
            text-transform: uppercase;
            letter-spacing: 1px;
            transition: background 0.3s;
        }

        .btn-submit:hover {
            background-color: #c1121f;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            footer {
                grid-template-columns: 1fr;
                text-align: center;
                gap: 50px;
            }

            .footer-center {
                justify-content: center;
                flex-wrap: wrap;
            }

            .footer-right {
                align-items: center;
            }

            .newsletter-form {
                justify-content: center;
                flex-wrap: wrap;
            }

            nav { display: none; } /* Simplified for mobile view simulation */
            header { justify-content: center; }
        }
    </style>
</head>
<body>

    <!-- HERO SECTION -->
    <section class="hero-section">
        <header>
            <div class="logo">
                <span>Elegant Affairs</span>
                <div class="logo-sub">OFF-PREMISE CATERING</div>
            </div>
            <nav>
                <ul>
                    <li><a href="#">About</a></li>
                    <li><a href="#">Events</a></li>
                    <li><a href="#">Press</a></li>
                    <li><a href="#">Blog</a></li>
                    <li><a href="#">Careers</a></li>
                    <li><a href="#" class="btn-contact-nav">Contact Us</a></li>
                </ul>
            </nav>
        </header>

        <div class="hero-text">
            <h1>Parties are<br>our passion.</h1>
        </div>
    </section>

    <!-- LOCATION STRIP -->
    <section class="location-strip">
        <div class="location-item">
            <h3>New York City</h3>
            <div class="location-line"></div>
        </div>
        <div class="location-item">
            <h3>Long Island</h3>
            <div class="location-line"></div>
        </div>
        <div class="location-item">
            <h3>Hamptons</h3>
            <div class="location-line"></div>
        </div>
    </section>

    <!-- ILLUSTRATION SECTION -->
    <section class="illustration-section">
        <!-- Using an SVG illustration to mimic the hand-drawn map style -->
        <svg class="map-placeholder-svg" viewBox="0 0 1000 400" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid meet">
            <!-- Background Clouds -->
            <path d="M150,100 Q180,70 220,100 T290,100 T360,100" fill="#f0f0f0" stroke="none"/>
            <path d="M450,130 Q480,100 520,130 T590,130" fill="#f0f0f0" stroke="none"/>
            <path d="M750,110 Q780,80 820,110 T890,110" fill="#f0f0f0" stroke="none"/>

            <!-- City Skyline (Left) -->
            <g transform="translate(50, 150)" stroke="#222" stroke-width="2" fill="white">
                <rect x="0" y="50" width="30" height="100" />
                <rect x="35" y="20" width="40" height="130" />
                <rect x="80" y="60" width="25" height="90" />
                <rect x="110" y="10" width="45" height="140" />
                <!-- Windows -->
                <line x1="45" y1="30" x2="65" y2="30" />
                <line x1="45" y1="50" x2="65" y2="50" />
                <line x1="120" y1="20" x2="145" y2="20" />
                <line x1="120" y1="40" x2="145" y2="40" />
            </g>

            <!-- Truck -->
            <g transform="translate(280, 260)" stroke="#222" stroke-width="2" fill="white">
                <rect x="0" y="10" width="50" height="30" rx="2" />
                <rect x="50" y="20" width="20" height="20" rx="2" />
                <circle cx="15" cy="42" r="6" fill="#222" stroke="none"/>
                <circle cx="55" cy="42" r="6" fill="#222" stroke="none"/>
                <text x="10" y="30" font-size="10" fill="#E63946" stroke="none" font-family="cursive">EA</text>
            </g>

            <!-- Houses (Middle) -->
            <g transform="translate(420, 240)" stroke="#222" stroke-width="1.5" fill="white">
                <rect x="0" y="10" width="40" height="30" />
                <polygon points="0,10 20,-5 40,10" fill="white" />

                <rect x="60" y="15" width="35" height="25" fill="#FADADD" /> <!-- Pink house hint -->
                <polygon points="60,15 77,2 95,15" fill="#FADADD" />

                <rect x="110" y="10" width="40" height="30" />
                <polygon points="110,10 130,-5 140,10" fill="white" />
            </g>

            <!-- Hamptons Area (Right) -->
            <g transform="translate(700, 250)" stroke="#222" stroke-width="1.5" fill="white">
                 <!-- Tent -->
                 <path d="M0,40 L25,10 L50,40 Z" fill="white" />
                 <line x1="25" y1="10" x2="25" y2="40" stroke-dasharray="2,2"/>

                 <!-- Beach House -->
                 <rect x="70" y="25" width="30" height="20" />
                 <polygon points="70,25 85,15 100,25" fill="white" />

                 <!-- Water hint -->
                 <path d="M110,45 Q130,35 150,45" fill="#E0E6ED" stroke="none" />
            </g>

             <!-- Helicopter -->
             <g transform="translate(800, 80)">
                <ellipse cx="20" cy="10" rx="18" ry="6" stroke="#222" stroke-width="1.5" fill="white"/>
                <line x1="5" y1="10" x2="-10" y2="10" stroke="#222" stroke-width="1.5"/> 
                <line x1="20" y1="4" x2="20" y2="-5" stroke="#222" stroke-width="1.5"/>
                <path d="M10,-5 L30,-5" stroke="#E63946" stroke-width="1.5"/> <!-- Rotor -->
             </g>

             <!-- Decorative elements -->
             <circle cx="250" cy="160" r="2" fill="#222" />
             <circle cx="265" cy="175" r="2" fill="#222" />
             <path d="M255,165 L275,185 M275,165 L255,185" stroke="#222" stroke-width="1" /> <!-- Star shape approx -->

        </svg>
    </section>

    <!-- SPACER BLOCK 1 -->
    <div class="spacer-block"></div>

    <!-- SPACER BLOCK 2 -->
    <div class="spacer-block"></div>

    <!-- FOOTER -->
    <footer>
        <div class="footer-left">
            <h2>It's party time</h2>
            <a href="#" class="footer-link">Contact Us</a>
            <div class="social-icons">
                <a href="#" class="social-icon">f</a>
                <a href="#" class="social-icon">y</a>
                <a href="#" class="social-icon">in</a>
            </div>
        </div>

        <div class="footer-center">
            <div class="address-col">
                <strong>240 West 30th Street<br>New York, NY 10001</strong>
                Main: 212.303.1052
            </div>
            <div class="address-col">
                <strong>110 Glen Cove Avenue<br>Glen Cove, New York</strong>
                Main: 516.676.5500
            </div>
            <div class="address-col">
                <strong>230 Elm Street<br>Southampton, New York</strong>
                Main: 631.283.2130
